package com.airesumebuilder.feature.ats.controller;
import com.airesumebuilder.common.dto.ApiResponse;import com.airesumebuilder.common.dto.Pagination;import com.airesumebuilder.feature.ats.service.AtsService;import com.airesumebuilder.security.CurrentUser;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/ats")public class AtsController{private final AtsService service;private final CurrentUser user;public AtsController(AtsService service,CurrentUser user){this.service=service;this.user=user;}@GetMapping("/health")public ResponseEntity<ApiResponse<String>>health(){return ResponseEntity.ok(ApiResponse.success("UP","ATS service is available."));}@PostMapping("/analyze")public ResponseEntity<ApiResponse<AtsService.Report>>analyze(@Valid@RequestBody AtsService.AnalyzeRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.analyze(user.email(),request),"ATS analysis completed."));}@GetMapping("/reports/{id}")public ResponseEntity<ApiResponse<AtsService.Report>>get(@PathVariable long id){return ResponseEntity.ok(ApiResponse.success(service.get(user.email(),id),"ATS report retrieved."));}@GetMapping("/resumes/{resumeId}/reports")public ResponseEntity<ApiResponse<List<AtsService.ReportSummary>>>list(@PathVariable long resumeId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){var result=service.list(user.email(),resumeId,page,size);int pages=(int)Math.ceil(result.total()/(double)result.size());return ResponseEntity.ok(ApiResponse.paginated(result.items(),new Pagination(result.page(),result.size(),result.total(),pages)));}}
